'use client';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef } from 'react';

export function VirtualList({ items }: { items: any[] }) {
  const parent = useRef<HTMLDivElement>(null);
  const v = useVirtualizer({ count: items.length || {{item_count}}, getScrollElement: () => parent.current, estimateSize: () => {{row_height}}, overscan: 8 });
  return (
    <div ref={parent} style={{ height: 400, overflow: 'auto' }}>
      <div style={{ height: v.getTotalSize(), position: 'relative' }}>
        {v.getVirtualItems().map(row => (
          <div key={row.key} style={{ position: 'absolute', top: 0, transform: `translateY(${row.start}px)`, height: row.size, width: '100%' }}>
            {items[row.index]?.label ?? row.index}
          </div>
        ))}
      </div>
    </div>
  );
}
